import { MdOutlineLibraryBooks } from "react-icons/md";
import { api } from "~/utils/api";
import { useState, Dispatch } from "react";
import { useDisclosure } from "@chakra-ui/react";

interface LibraryProps {
  setInputMessage: Dispatch<>;
}

const Library: React.FC<LibraryProps> = ({ setInputMessage }) => {
  const utils = api.useContext();
  const [editedName, setEditedName] = useState("");
  const [editedPrompt, setEditedPrompt] = useState("");
  const [selectedTargetPrompt, setSelectedTargetPrompt] = useState("");
  const prompts = api.prompt.all.useQuery();
  const { onClose } = useDisclosure();

  const upsertPrompt = api.prompt.upsert.useMutation({
    onSuccess: async () => utils.prompt.invalidate(),
  });

  const deletePrompt = api.prompt.delete.useMutation({
    onSuccess: async () => utils.prompt.invalidate(),
  });

  const handleEdit = async (prompt: { id: string; name: string; prompt: string }) => {
    setEditedName(prompt.name);
    setEditedPrompt(prompt.prompt);
  };

  const handleSave = async () => {
    if (editedName) {
      try {
        await upsertPrompt.mutate({
          id: editedName,
          name: editedName,
          prompt: editedPrompt,
        });
        setEditedName("");
        setEditedPrompt("");
      } catch (error) {
        console.error(error);
      }
    }
  };

  const handleDelete = async (id: string) => {
    try {
      await deletePrompt.mutate({ id });
    } catch (error) {
      console.error(error);
    }
  };

  const handleSelect = async (id: string) => {
    setSelectedTargetPrompt(id);
  };

  const renderPromptList = () => {
    return prompts.data?.map((prompt) => (
      <li
        key={prompt.id}
        className="flex justify-between items-center mb-4"
      >
        <span>{prompt.name}</span>
        <span>{prompt.prompt}</span>
        <button
          onClick={() => handleEdit(prompt)}
          className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded"
        >
          Edit
        </button>
        <button
          onClick={() => handleDelete(prompt.id)}
          className="bg-red-500 hover:bg-red-700 text-white font-bold py-2 px-4 rounded"
        >
          Delete
        </button>
      </li>
    ));
  };

  return (
    <div className="flex flex-col justify-center h-screen">
      <div className="flex justify-center mb-4">
        <MdOutlineLibraryBooks size={24} />
      </div>
      <div className="flex flex-col justify-center w-full p-4">
        <h2 className="text-2xl font-bold mb-4">Library</h2>
        <ul className="flex flex-col justify-center w-full p-4">{renderPromptList()}</ul>
      </div>
    </div>
  );
};

export default Library;
