class Solution {
    public int fullJustify(String[] words, int maxWidth) {
        List<String> res = new ArrayList<>();
        StringBuilder sb = new StringBuilder();
        int len = 0;
        for (String word : words) {
            if (len + sb.length() + word.length() > maxWidth) {
                int gap = (maxWidth - len) / (sb.length() - 1);
                int extra = (maxWidth - len) % (sb.length() - 1);
                for (int i = 0; i < sb.length() - 1; i++) {
                    sb.insert(i + 1, " ".repeat(gap));
                    if (i < extra) {
                        sb.insert(i + 1, " ");
                    }
                }
                res.add(sb.toString());
                sb.setLength(0);
                len = 0;
            }
            sb.append(word);
            len += word.length();
        }
        if (sb.length() > 0) {
            res.add(sb.append(" ".repeat(maxWidth - sb.length())).toString());
        }
        return res.size();
    }
}
```
